1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const CURSE_SURCHARGE_RATE = 0.5;
4	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
5	const HIGH_ENCHANTMENT_THRESHOLD = 5;
6	const LOYALTY_DISCOUNT_RATE = 0.2;
7	const LOYALTY_THRESHOLD_YEARS = 2;
8	const FOLLOWUP_CONTRACT_DISCOUNT_RATE = 0.15;
9	const COMPONENT_BLOCK_BASE = 60;
10	const COMPONENT_BLOCK_SIZE = 3;
11	const DEDUCTIBLE_PER_DAMAGE = 100;
12	const CAP_MULTIPLIER = 2;
13	const HIGH_ENCHANTMENT_PAYOUT_THRESHOLD = 8;
14	const HIGH_ENCHANTMENT_PAYOUT_RATE = 0.5;
15	
16	const BASE_PREMIUM: Record<string, number> = {
17	  sword: 100,
18	  amulet: 60,
19	  staff: 80,
20	  potion: 40,
21	  rune: 25,
22	  moonstone: 25,
23	};
24	
25	const INSURANCE_VALUE: Record<string, number> = {
26	  sword: 1000,
27	  amulet: 600,
28	  staff: 800,
29	  potion: 400,
30	  rune: 250,
31	  moonstone: 250,
32	};
33	
34	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
35	
36	type Item = { type: string; cursed?: boolean; enchantment?: number; material?: string };
37	type Customer = { yearsWithMHPCO: number };
38	type QuoteStep = { op: "quote"; items: Item[] };
39	type Damage = { itemType: string; amount: number };
40	type ClaimStep = {
41	  op: "claim";
42	  policy: number;
43	  incident: { cause: string; damages: Damage[] };
44	};
45	type Step = QuoteStep | ClaimStep;
46	type Scenario = { customer: Customer; steps: Step[] };
47	
48	type QuoteResult = { premium: number };
49	type ClaimResult = { payout: number; remainingCap: number };
50	type StepResult = QuoteResult | ClaimResult;
51	
52	type Policy = { items: Item[]; remainingCap: number };
53	
54	const countBy = <T>(values: T[], keyOf: (value: T) => string): Map<string, number> =>
55	  values.reduce((counts, value) => {
56	    const key = keyOf(value);
57	    return counts.set(key, (counts.get(key) ?? 0) + 1);
58	  }, new Map<string, number>());
59	
60	const countByType = (items: Item[]): Map<string, number> =>
61	  countBy(items, (item) => item.type);
62	
63	const basePremiumForGroup = (type: string, count: number): number =>
64	  COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE
65	    ? COMPONENT_BLOCK_BASE
66	    : count * BASE_PREMIUM[type];
67	
68	const basePremiumForItems = (items: Item[]): number =>
69	  [...countByType(items)].reduce(
70	    (sum, [type, count]) => sum + basePremiumForGroup(type, count),
71	    0,
72	  );
73	
74	const enchantmentLevel = (item: Item): number => item.enchantment ?? 0;
75	
76	const surchargeRateForItem = (item: Item): number =>
77	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
78	  (enchantmentLevel(item) >= HIGH_ENCHANTMENT_THRESHOLD ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
79	
80	const itemSurcharges = (items: Item[]): number =>
81	  items.reduce(
82	    (sum, item) => sum + BASE_PREMIUM[item.type] * surchargeRateForItem(item),
83	    0,
84	  );
85	
86	const roundUpForInsurer = (premium: number): number => Math.ceil(premium);
87	const roundDownForInsurer = (payout: number): number => Math.floor(payout);
88	
89	const loyaltyDiscountRate = (customer: Customer): number =>
90	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? LOYALTY_DISCOUNT_RATE : 0;
91	
92	const followupDiscountRate = (quoteIndex: number): number =>
93	  quoteIndex > 0 ? FOLLOWUP_CONTRACT_DISCOUNT_RATE : 0;
94	
95	const withPolicyWideModifiers = (
96	  base: number,
97	  customer: Customer,
98	  quoteIndex: number,
99	): number =>
100	  base +
101	  base * FIRST_INSURANCE_SURCHARGE_RATE -
102	  base * loyaltyDiscountRate(customer) -
103	  base * followupDiscountRate(quoteIndex);
104	
105	const quotePremium = (
106	  items: Item[],
107	  customer: Customer,
108	  quoteIndex: number,
109	): number =>
110	  roundUpForInsurer(
111	    withPolicyWideModifiers(basePremiumForItems(items), customer, quoteIndex) +
112	      itemSurcharges(items),
113	  ) + PROCESSING_FEE;
114	
115	const insuranceSumFor = (items: Item[]): number =>
116	  items.reduce((sum, item) => sum + INSURANCE_VALUE[item.type], 0);
117	
118	const initialCapFor = (items: Item[]): number =>
119	  insuranceSumFor(items) * CAP_MULTIPLIER;
120	
121	const policyFrom = (items: Item[]): Policy => ({
122	  items,
123	  remainingCap: initialCapFor(items),
124	});
125	
126	const reimbursementRateFor = (item: Item): number =>
127	  enchantmentLevel(item) >= HIGH_ENCHANTMENT_PAYOUT_THRESHOLD ? HIGH_ENCHANTMENT_PAYOUT_RATE : 1;
128	
129	const payoutForDamage = (item: Item, amount: number): number =>
130	  roundDownForInsurer(Math.max(0, amount * reimbursementRateFor(item) - DEDUCTIBLE_PER_DAMAGE));
131	
132	const findInsuredItem = (items: Item[], itemType: string): Item =>
133	  items.find((item) => item.type === itemType)!;
134	
135	const totalPayoutFor = ({ items }: Policy, damages: Damage[]): number =>
136	  damages.reduce(
137	    (sum, { itemType, amount }) => sum + payoutForDamage(findInsuredItem(items, itemType), amount),
138	    0,
139	  );
140	
141	const validateDamageAmounts = (damages: Damage[]): void => {
142	  damages.forEach(({ amount }) => {
143	    if (amount < 0) {
144	      throw new Error(`Damage amount must be non-negative`);
145	    }
146	  });
147	};
148	
149	const validateDamageCounts = (policy: Policy, damages: Damage[]): void => {
150	  const insuredCounts = countByType(policy.items);
151	  countBy(damages, (damage) => damage.itemType).forEach((damageCount, itemType) => {
152	    if (damageCount > (insuredCounts.get(itemType) ?? 0)) {
153	      throw new Error(`Damage entries for ${itemType} exceed insured count`);
154	    }
155	  });
156	};
157	
158	const validateDamages = (policy: Policy, damages: Damage[]): void => {
159	  validateDamageAmounts(damages);
160	  validateDamageCounts(policy, damages);
161	};
162	
163	const applyClaim = (
164	  policy: Policy,
165	  damages: Damage[],
166	): { policy: Policy; result: ClaimResult } => {
167	  validateDamages(policy, damages);
168	  const payout = Math.min(totalPayoutFor(policy, damages), policy.remainingCap);
169	  const remainingCap = policy.remainingCap - payout;
170	  return { policy: { ...policy, remainingCap }, result: { payout, remainingCap } };
171	};
172	
173	const validateItemTypes = (items: Item[]): void => {
174	  items.forEach((item) => {
175	    if (!(item.type in BASE_PREMIUM)) {
176	      throw new Error(`Unknown item type: ${item.type}`);
177	    }
178	  });
179	};
180	
181	const handleQuote = (
182	  { items }: QuoteStep,
183	  customer: Customer,
184	  policies: Map<number, Policy>,
185	  index: number,
186	): QuoteResult => {
187	  validateItemTypes(items);
188	  const premium = quotePremium(items, customer, policies.size);
189	  policies.set(index, policyFrom(items));
190	  return { premium };
191	};
192	
193	const handleClaim = (
194	  step: ClaimStep,
195	  policies: Map<number, Policy>,
196	): ClaimResult => {
197	  const { policy, result } = applyClaim(policies.get(step.policy)!, step.incident.damages);
198	  policies.set(step.policy, policy);
199	  return result;
200	};
201	
202	export const runScenario = ({ customer, steps }: Scenario): { results: StepResult[] } => {
203	  const policies = new Map<number, Policy>();
204	  const results = steps.map((step, index) =>
205	    step.op === "quote"
206	      ? handleQuote(step, customer, policies, index)
207	      : handleClaim(step, policies),
208	  );
209	  return { results };
210	};
